#![cfg_attr(not(target_os = "macos"), allow(dead_code))]

use kikigaki_core::engine::EnginePhase;
use kikigaki_core::session::State;

// 36x36 RGBA PNGs (18pt @2x) generated by scripts/icons/make_icons.py.
const IDLE: &[u8] = include_bytes!("../icons/tray/idle.png");
const RECORDING: &[u8] = include_bytes!("../icons/tray/recording.png");
const FINALIZING: &[u8] = include_bytes!("../icons/tray/finalizing.png");
const LOADING: &[u8] = include_bytes!("../icons/tray/loading.png");
const DISCONNECTED: &[u8] = include_bytes!("../icons/tray/disconnected.png");

/// Menu-bar mark: PNG bytes plus whether macOS should treat it as a template
/// image (tinted to match the light/dark menu bar).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TrayMark {
    pub png: &'static [u8],
    pub template: bool,
}

pub fn mark(state: State, phase: EnginePhase) -> TrayMark {
    let png = match state {
        State::Idle => IDLE,
        State::Recording => RECORDING,
        State::Finalizing => FINALIZING,
        State::Disconnected if phase == EnginePhase::Starting => LOADING,
        State::Disconnected => DISCONNECTED,
    };
    TrayMark {
        png,
        template: state != State::Recording,
    }
}

/// Shown from launch until the first status snapshot arrives.
pub fn initial_mark() -> TrayMark {
    mark(State::Disconnected, EnginePhase::Starting)
}

pub fn tooltip(state: State, phase: EnginePhase) -> &'static str {
    match state {
        State::Idle => "kikigaki — idle",
        State::Recording => "kikigaki — recording",
        State::Finalizing => "kikigaki — finalizing",
        State::Disconnected if phase == EnginePhase::Starting => "kikigaki — loading",
        State::Disconnected => "kikigaki — disconnected",
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn png_header(png: &[u8]) -> (u32, u32, u8) {
        assert_eq!(&png[..8], b"\x89PNG\r\n\x1a\n");
        assert_eq!(&png[12..16], b"IHDR");
        let width = u32::from_be_bytes(png[16..20].try_into().unwrap());
        let height = u32::from_be_bytes(png[20..24].try_into().unwrap());
        (width, height, png[25])
    }

    #[test]
    fn state_maps_to_tooltip_text() {
        assert_eq!(tooltip(State::Idle, EnginePhase::Ready), "kikigaki — idle");
        assert_eq!(
            tooltip(State::Recording, EnginePhase::Ready),
            "kikigaki — recording"
        );
        assert_eq!(
            tooltip(State::Finalizing, EnginePhase::Ready),
            "kikigaki — finalizing"
        );
        assert_eq!(
            tooltip(State::Disconnected, EnginePhase::Failed),
            "kikigaki — disconnected"
        );
        assert_eq!(
            tooltip(State::Disconnected, EnginePhase::Starting),
            "kikigaki — loading"
        );
    }

    #[test]
    fn state_maps_to_mark_and_template_flag() {
        for (state, phase, png, template) in [
            (State::Idle, EnginePhase::Ready, IDLE, true),
            (State::Recording, EnginePhase::Ready, RECORDING, false),
            (State::Finalizing, EnginePhase::Ready, FINALIZING, true),
            (State::Disconnected, EnginePhase::Starting, LOADING, true),
            (State::Disconnected, EnginePhase::Failed, DISCONNECTED, true),
            (State::Disconnected, EnginePhase::Ready, DISCONNECTED, true),
        ] {
            assert_eq!(mark(state, phase), TrayMark { png, template });
        }
    }

    #[test]
    fn marks_are_distinct_36_pixel_rgba_pngs() {
        let marks = [IDLE, RECORDING, FINALIZING, LOADING, DISCONNECTED];
        for (i, png) in marks.iter().enumerate() {
            // Color type 6 = RGBA; tray-icon scales to 18pt, so 36px is @2x.
            assert_eq!(png_header(png), (36, 36, 6));
            assert!(marks[i + 1..].iter().all(|other| other != png));
        }
    }

    #[test]
    fn launch_shows_the_loading_template_mark() {
        assert_eq!(
            initial_mark(),
            TrayMark {
                png: LOADING,
                template: true
            }
        );
    }
}
